@Service
public class CareerAiService {
    private static final Logger log=LoggerFactory.getLogger(CareerAiService.class);
    private final AiProperties properties;private final ObjectMapper json;private final RestClient client;private final ProfileRepository profiles;private final UserSkillRepository skills;private final ResumeAnalysisRepository analyses;private final AssessmentAttemptRepository attempts;private final CareerPlanService plans;private final CareerSkillTaxonomy taxonomy;private final DsaPracticeService dsa;private final InterviewSessionRepository interviewSessions;
    public CareerAiService(AiProperties properties,ObjectMapper json,ProfileRepository profiles,UserSkillRepository skills,ResumeAnalysisRepository analyses,AssessmentAttemptRepository attempts,CareerPlanService plans,CareerSkillTaxonomy taxonomy,DsaPracticeService dsa,InterviewSessionRepository interviewSessions){this.properties=properties;this.json=json;this.profiles=profiles;this.skills=skills;this.analyses=analyses;this.attempts=attempts;this.plans=plans;this.taxonomy=taxonomy;this.dsa=dsa;this.interviewSessions=interviewSessions;var factory=new SimpleClientHttpRequestFactory();factory.setConnectTimeout(properties.connectTimeout());factory.setReadTimeout(properties.requestTimeout());this.client=RestClient.builder().baseUrl("https://generativelanguage.googleapis.com").requestFactory(factory).build();}

    @Transactional(readOnly=true) public InterviewResponse interview(User user,InterviewRequest request){
        if(taxonomy.find(request.targetCareer()).isEmpty())throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"Unsupported target career");
        Map<String,String> evidence=evidence(user);String prompt="You are an adaptive career interview coach. Use only the supplied evidence. Do not invent profile facts or scores. Mode="+request.mode()+"; target="+request.targetCareer()+"; focus="+safe(request.focusArea())+". Evidence="+write(evidence)+". Previous question="+safe(request.previousQuestion())+". Student answer="+safe(request.answer())+". Return JSON only with question (one next interview question), feedback {strengths: string[], needsImprovement: string[], nextFocus: string, scores with technicalCorrectness, relevance, answerStructure, completeness, communicationClarity integers 0-100, suggestedAnswer: string, topicsToReview: string[]}. If there is no prior answer, feedback scores must all be 0 and lists empty. Feedback is coaching, not hiring evaluation.";
        JsonNode value=generate("INTERVIEW",prompt,interviewSchema());JsonNode feedback=value.path("feedback"),scores=feedback.path("scores");return new InterviewResponse(request.targetCareer(),request.mode(),required(value,"question"),new InterviewFeedback(strings(feedback.path("strengths")),strings(feedback.path("needsImprovement")),feedback.path("nextFocus").asText(""),new InterviewScores(score(scores,"technicalCorrectness"),score(scores,"relevance"),score(scores,"answerStructure"),score(scores,"completeness"),score(scores,"communicationClarity")),feedback.path("suggestedAnswer").asText(""),strings(feedback.path("topicsToReview"))),"GEMINI",properties.geminiModel(),"AI-generated coaching for practice only. It is not a hiring, employability, psychological, or recruiter assessment.");
    }

    @Transactional(readOnly=true) public CopilotResponse copilot(User user,CopilotRequest request){
        Map<String,String> evidence=evidence(user);String prompt="You are Career Guidance AI Copilot. Answer the student's question using only CURRENT EVIDENCE. Never invent a score, skill, recommendation, or outcome. Explicitly say when evidence is unavailable. Do not describe model confidence as employment probability. Question="+request.question()+". CURRENT EVIDENCE="+write(evidence)+". Return JSON only with aiGuidance as a concise string.";
        JsonNode value=generate("COPILOT",prompt,Map.of("type","OBJECT","properties",Map.of("aiGuidance",Map.of("type","STRING")),"required",List.of("aiGuidance")));
        return new CopilotResponse(evidence,required(value,"aiGuidance"),"GEMINI",properties.geminiModel(),"AI-generated guidance grounded in the displayed evidence. Deterministic platform values remain the source of truth.");
    }

    private Map<String,String> evidence(User user){
        var profile=profiles.findByUserId(user.getId()).orElseThrow(()->new NotFoundException("Student profile not found"));var values=new LinkedHashMap<String,String>();values.put("Degree",available(profile.getDegree()));values.put("Target career",available(profile.getTargetRole()));values.put("Experience level",profile.getExperienceLevel()==null?"Unavailable":profile.getExperienceLevel().name());values.put("Saved skills",skills.findByUserIdOrderBySkillDisplayName(user.getId()).stream().map(v->v.getSkill().getDisplayName()+" ("+v.getProficiencyLevel()+")").collect(java.util.stream.Collectors.joining(", ")));
        analyses.findFirstByResumeUserIdAndResumeActiveTrueOrderByCreatedAtDesc(user.getId()).ifPresentOrElse(v->values.put("Latest resume ATS",v.getAtsScore()+"%"),()->values.put("Latest resume ATS","Unavailable"));attempts.findFirstByUserIdAndStatusOrderByCreatedAtDesc(user.getId(),AttemptStatus.SUBMITTED).ifPresentOrElse(v->values.put("Latest assessment",v.getScorePercentage()==null?"Unavailable":v.getScorePercentage()+"%"),()->values.put("Latest assessment","Unavailable"));var plan=plans.current(user);if(plan==null){values.put("Placement readiness","Unavailable");values.put("Career skill coverage","Unavailable");values.put("Roadmap task status","Unavailable");values.put("Skill gaps","Unavailable");}else{values.put("Selected career",plan.selectedCareer());values.put("Placement readiness",plan.placementReadiness().score()+"/100");values.put("Career skill coverage",plan.skillGap().score()+"%");values.put("Roadmap task status",plan.progressPercentage()+"% self-tracked");values.put("Skill gaps",java.util.stream.Stream.of(plan.skillGap().missingCore(),plan.skillGap().missingSupporting(),plan.skillGap().needsImprovement()).flatMap(List::stream).map(v->v.skill()+" ("+v.state()+")").distinct().collect(java.util.stream.Collectors.joining(", ")));}values.putAll(dsa.copilotEvidence(user));interviewSessions.findFirstByUserIdAndStatusOrderByCompletedAtDesc(user.getId(),InterviewStatus.COMPLETED).ifPresentOrElse(v->{values.put("Latest interview",v.getTargetCareer()+" · "+v.getInterviewType()+" · "+v.getMode());values.put("Latest interview coaching score",v.getOverallCoachingScore()+"/100");},()->values.put("Latest interview","Unavailable"));return values;
    }
    private JsonNode generate(String operation,String prompt,Map<String,Object> schema){if(!properties.enabled()||properties.geminiApiKey()==null||properties.geminiApiKey().isBlank()){log.warn("Career AI coaching skipped operation={} model={} reason=missing_or_disabled_configuration",operation,properties.geminiModel());throw unavailable();}Map<String,Object>body=Map.of("contents",List.of(Map.of("role","user","parts",List.of(Map.of("text",prompt)))),"generationConfig",Map.of("temperature",0.2,"maxOutputTokens",2048,"responseMimeType","application/json","responseSchema",schema));long started=System.nanoTime();String model=properties.geminiModel();try{JsonNode response;try{response=executeWithRetry(operation,model,body,started);}catch(RestClientException primary){if(!transientFailure(primary))throw primary;String fallback=discoverFallback(model,operation,started);if(fallback==null)throw primary;model=fallback;log.info("Career AI fallback selected operation={} primaryModel={} fallbackModel={} elapsedMs={}",operation,properties.geminiModel(),fallback,elapsedMs(started));response=execute(fallback,body);}String text=response==null?"":response.path("candidates").path(0).path("content").path("parts").path(0).path("text").asText();JsonNode result=json.readTree(text);log.info("Career AI coaching completed operation={} model={} httpStatus=200 elapsedMs={}",operation,model,elapsedMs(started));return result;}catch(RestClientResponseException e){ProviderError provider=providerError(e);log.warn("Career AI provider request failed operation={} model={} httpStatus={} providerCode={} providerMessage={} elapsedMs={}",operation,model,e.getStatusCode().value(),provider.code(),provider.message(),elapsedMs(started));throw unavailable();}catch(RestClientException e){log.warn("Career AI transport failed operation={} model={} reason={} elapsedMs={}",operation,model,safeLog(e.getClass().getSimpleName()+": "+e.getMessage()),elapsedMs(started));throw unavailable();}catch(Exception e){log.warn("Career AI response invalid operation={} model={} reason={} elapsedMs={}",operation,model,safeLog(e.getClass().getSimpleName()+": "+e.getMessage()),elapsedMs(started));throw unavailable();}}
    private JsonNode executeWithRetry(String operation,String model,Map<String,Object> body,long started){RestClientException last=null;for(int attempt=1;attempt<=3;attempt++)try{return execute(model,body);}catch(RestClientResponseException e){last=e;ProviderError provider=providerError(e);if(!transientFailure(e)||attempt==3)throw e;long backoff=attempt*1000L;log.warn("Career AI transient provider failure; retrying operation={} model={} attempt={} httpStatus={} providerCode={} providerMessage={} backoffMs={} elapsedMs={}",operation,model,attempt,e.getStatusCode().value(),provider.code(),provider.message(),backoff,elapsedMs(started));sleep(backoff);}catch(RestClientException e){last=e;if(attempt==3)throw e;long backoff=attempt*1000L;log.warn("Career AI transient transport failure; retrying operation={} model={} attempt={} reason={} backoffMs={} elapsedMs={}",operation,model,attempt,e.getClass().getSimpleName(),backoff,elapsedMs(started));sleep(backoff);}throw last;}
    private JsonNode execute(String model,Map<String,Object> body){String raw=client.post().uri("/v1beta/models/{model}:generateContent",model).header("x-goog-api-key",properties.geminiApiKey()).contentType(MediaType.APPLICATION_JSON).accept(MediaType.APPLICATION_JSON).body(body).retrieve().body(String.class);try{return raw==null?null:json.readTree(raw);}catch(Exception e){throw new RestClientException("Gemini returned an invalid JSON response envelope",e);}}
    private String discoverFallback(String primary,String operation,long started){try{JsonNode response=client.get().uri("/v1beta/models?pageSize=1000").header("x-goog-api-key",properties.geminiApiKey()).retrieve().body(JsonNode.class);if(response==null)return null;return java.util.stream.StreamSupport.stream(response.path("models").spliterator(),false).filter(value->java.util.stream.StreamSupport.stream(value.path("supportedGenerationMethods").spliterator(),false).anyMatch(method->"generateContent".equals(method.asText()))).map(value->value.path("name").asText().replaceFirst("^models/","")).filter(name->!name.equals(primary)).filter(name->{String lower=name.toLowerCase(java.util.Locale.ROOT);return lower.contains("flash")&&!lower.matches(".*(image|audio|live|tts|computer|omni|transcribe).* ".trim());}).sorted(java.util.Comparator.comparingInt(this::fallbackRank).thenComparing(java.util.Comparator.naturalOrder())).findFirst().orElse(null);}catch(RuntimeException e){log.warn("Career AI model discovery failed operation={} primaryModel={} reason={} elapsedMs={}",operation,primary,e.getClass().getSimpleName(),elapsedMs(started));return null;}}
    private int fallbackRank(String model){String lower=model.toLowerCase(java.util.Locale.ROOT);if(lower.equals("gemini-3.5-flash"))return 0;if(lower.equals("gemini-2.5-flash"))return 1;if(lower.equals("gemini-flash-latest"))return 2;if(lower.contains("preview"))return 5;return 3;}private boolean transientFailure(RuntimeException e){return(e instanceof RestClientException&&!(e instanceof RestClientResponseException))||(e instanceof RestClientResponseException response&&(response.getStatusCode().value()==429||response.getStatusCode().value()==503));}private long elapsedMs(long started){return(System.nanoTime()-started)/1_000_000;}private void sleep(long ms){try{Thread.sleep(ms);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("Career AI retry interrupted",e);}}
    private ProviderError providerError(RestClientResponseException exception){try{JsonNode error=json.readTree(exception.getResponseBodyAsString()).path("error");return new ProviderError(safeLog(error.path("status").asText(String.valueOf(exception.getStatusCode().value()))),safeLog(error.path("message").asText("Provider request failed")));}catch(Exception ignored){return new ProviderError(String.valueOf(exception.getStatusCode().value()),"Provider request failed");}}private String safeLog(String value){if(value==null)return"unknown";String sanitized=value.replaceAll("[\\r\\n\\t]+"," ").replaceAll("(?i)(key|token|authorization)[=: ]+[^ ,;]+","$1=[redacted]").strip();return sanitized.substring(0,Math.min(300,sanitized.length()));}private record ProviderError(String code,String message){}
    private Map<String,Object> interviewSchema(){Map<String,Object>score=Map.of("type","INTEGER","minimum",0,"maximum",100);Map<String,Object>scores=Map.of("type","OBJECT","properties",Map.of("technicalCorrectness",score,"relevance",score,"answerStructure",score,"completeness",score,"communicationClarity",score),"required",List.of("technicalCorrectness","relevance","answerStructure","completeness","communicationClarity"));Map<String,Object>feedback=Map.of("type","OBJECT","properties",Map.of("strengths",Map.of("type","ARRAY","items",Map.of("type","STRING")),"needsImprovement",Map.of("type","ARRAY","items",Map.of("type","STRING")),"nextFocus",Map.of("type","STRING"),"scores",scores,"suggestedAnswer",Map.of("type","STRING"),"topicsToReview",Map.of("type","ARRAY","items",Map.of("type","STRING"))),"required",List.of("strengths","needsImprovement","nextFocus","scores","suggestedAnswer","topicsToReview"));return Map.of("type","OBJECT","properties",Map.of("question",Map.of("type","STRING"),"feedback",feedback),"required",List.of("question","feedback"));}
    private int score(JsonNode value,String name){return Math.max(0,Math.min(100,value.path(name).asInt(0)));}
    private ApiException unavailable(){return new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"AI coaching is temporarily unavailable");}private String write(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw unavailable();}}private String required(JsonNode value,String name){String result=value.path(name).asText("").trim();if(result.isEmpty())throw unavailable();return result;}private List<String> strings(JsonNode value){if(!value.isArray())return List.of();var result=new java.util.ArrayList<String>();value.forEach(v->{if(!v.asText("").isBlank())result.add(v.asText().trim());});return List.copyOf(result);}private String safe(String value){return value==null?"Unavailable":value;}private String available(String value){return value==null||value.isBlank()?"Unavailable":value;}
}
